// Package xrepo holds the cross-repository consistency suite between this repository (the root: Go) and unicity-pos-contracts
// (custody and election: Solidity). See README.md.
package xrepo

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"math/big"
	"os"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/unicitynetwork/bft-core/evmassign"
	"github.com/unicitynetwork/bft-core/rootchain/consensus/storage"
	"github.com/unicitynetwork/bft-core/rootrecords"
)

// The contracts' own fixture of a published election result (generated by PublicationFixture.t.sol; evmassign and evmstate hold
// copies and reproduce every word of it). This suite takes the identities and ids from it and nothing else.
const publicationPath = "../evmassign/testdata/publication.json"

// goRecordsPath is produced HERE (XREPO_UPDATE=1 go test ./xrepo) and replayed verbatim by the contracts (XRepoRecords.t.sol).
const goRecordsPath = "testdata/go-records.json"

// custodyViewPath is produced by the contracts (XRepoRecords.t.sol, P85_WRITE_FIXTURES=true) after custody applied the records.
const custodyViewPath = "testdata/custody-view.json"

type pubIdentity struct {
	ID            uint64   `json:"id"`
	Generation    uint64   `json:"generation"`
	Weight        uint64   `json:"weight"`
	RawWeight     uint64   `json:"rawWeight"`
	OperatorPayee string   `json:"operatorPayee"`
	RootKey       string   `json:"rootKey"`
	EVMKey        string   `json:"evmKey"`
	LotIDs        []uint64 `json:"lotIds"`
}

type publication struct {
	Deployment struct {
		NetworkWord string `json:"networkWord"`
		ChainID     uint64 `json:"chainId"`
		Custody     string `json:"custody"`
		Election    string `json:"election"`
	} `json:"deployment"`
	ResultID              string        `json:"resultId"`
	AssignmentID          string        `json:"assignmentId"`
	IncumbentAssignmentID string        `json:"incumbentAssignmentId"`
	Identities            []pubIdentity `json:"identities"`
	IncumbentIdentities   []pubIdentity `json:"incumbentIdentities"`
	Expected              struct {
		ExposureDigest          string `json:"exposureDigest"`
		KeyDigest               string `json:"keyDigest"`
		IncumbentExposureDigest string `json:"incumbentExposureDigest"`
		IncumbentKeyDigest      string `json:"incumbentKeyDigest"`
	} `json:"expected"`
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(strings.TrimPrefix(s, "0x"))
	require.NoError(t, err)
	return b
}

func h32(t *testing.T, s string) (out [32]byte) {
	t.Helper()
	b := unhex(t, s)
	require.Len(t, b, 32)
	copy(out[:], b)
	return out
}

func hx(b []byte) string { return "0x" + hex.EncodeToString(b) }

func label(s string) [32]byte { return sha256.Sum256([]byte(s)) }

func identities(t *testing.T, list []pubIdentity) []evmassign.Identity {
	t.Helper()
	out := make([]evmassign.Identity, len(list))
	for i, x := range list {
		var sid [32]byte
		new(big.Int).SetUint64(x.ID).FillBytes(sid[24:])
		lots := evmassign.LotsDigest(x.LotIDs)
		out[i] = evmassign.Identity{
			StakingID: sid[:], Generation: x.Generation, RootNodeID: "root-" + string(rune('a'+i)), RootKey: unhex(t, x.RootKey),
			EVMNodeID: "evm-" + string(rune('a'+i)), EVMKey: unhex(t, x.EVMKey), Weight: x.Weight, RawWeight: x.RawWeight,
			OperatorPayee: unhex(t, x.OperatorPayee), ExposureDigest: lots[:],
		}
	}
	return out
}

func loadPublication(t *testing.T) (publication, evmassign.Deployment) {
	t.Helper()
	raw, err := os.ReadFile(publicationPath)
	require.NoError(t, err)
	var p publication
	require.NoError(t, json.Unmarshal(raw, &p))
	d := evmassign.Deployment{NetworkWord: h32(t, p.Deployment.NetworkWord)}
	new(big.Int).SetUint64(p.Deployment.ChainID).FillBytes(d.ChainID[:])
	copy(d.Custody[:], unhex(t, p.Deployment.Custody))
	return p, d
}

// ---- the file this repository produces ----

type recordJSON struct {
	Index       uint64 `json:"index"`
	RecordID    string `json:"recordId"`
	Predecessor string `json:"predecessor"`
	Kind        uint8  `json:"kind"`
	KindName    string `json:"kindName"`
	Progress    uint64 `json:"progress"`
	UCTime      uint64 `json:"ucTime"`
	Data        string `json:"data"`
}

// assignmentJSON is what the root holds about an assignment once the branch's records are in the log, in custody's terms.
type assignmentJSON struct {
	Role           string `json:"role"` // genesis, primary, recovery
	AssignmentID   string `json:"assignmentId"`
	ExposureDigest string `json:"exposureDigest"`
	KeyDigest      string `json:"keyDigest"`
	State          string `json:"state"` // active, reserved, aborted
	Closed         bool   `json:"closed"`
	Pending        bool   `json:"pending"` // its closure is staged, waiting for the RecoveryAck
	HRound         uint64 `json:"hRound"`
	PClose         uint64 `json:"pClose"`
	TClose         uint64 `json:"tClose"`
	Offset         uint64 `json:"offset"`
	FirstRound     uint64 `json:"firstRound"`
	RootEpoch      uint64 `json:"rootEpoch"`
}

type stepJSON struct {
	AfterRecords        int              `json:"afterRecords"` // custody's state once this many records of the branch are applied
	LastAckedAssignment string           `json:"lastAckedAssignment"`
	PendingAssignment   string           `json:"pendingAssignment"`
	SessionState        string           `json:"sessionState"` // open, closed, acked, recovered
	Assignments         []assignmentJSON `json:"assignments"`
}

type branchJSON struct {
	Name    string       `json:"name"`
	Records []recordJSON `json:"records"`
	Steps   []stepJSON   `json:"steps"`
}

type goRecords struct {
	Format               string       `json:"format"`
	Note                 string       `json:"note"`
	ResultID             string       `json:"resultId"`
	GenesisAssignmentID  string       `json:"genesisAssignmentId"`
	PrimaryAssignmentID  string       `json:"primaryAssignmentId"`
	RecoveryAssignmentID string       `json:"recoveryAssignmentId"`
	RecoveryRootEpoch    uint64       `json:"recoveryRootEpoch"`
	RecoveryEVMEpoch     uint64       `json:"recoveryEvmEpoch"`
	Branches             []branchJSON `json:"branches"`
}

var kindNames = map[rootrecords.Kind]string{
	rootrecords.KindSessionClosed: "SessionClosed", rootrecords.KindAck: "Ack", rootrecords.KindRecoveryAck: "RecoveryAck",
	rootrecords.KindClosure: "Closure", rootrecords.KindRetirement: "Retirement",
}

func recordOf(r rootrecords.Record) recordJSON {
	return recordJSON{Index: r.Index, RecordID: hx(r.ID[:]), Predecessor: hx(r.Predecessor[:]), Kind: uint8(r.Kind), KindName: kindNames[r.Kind],
		Progress: r.Progress, UCTime: r.UCTime, Data: hx(r.Data)}
}

// The rounds of the scenario. Custody's genesis assignment starts at round 1 with offset 0 (root epoch 1); the election of the
// publication fixture ran at progress 100000 and UC time 604800, so everything here is after it.
const (
	genesisFirst = 1
	h1           = 100_100 // H of the handoff G -> J, ordered in root epoch 1
	jFirst       = 100_110 // J's activation round (root epoch 2)
	h2           = 100_150 // H of the next handoff, ordered in root epoch 2
	next2First   = 100_160 // the first round of root epoch 3
	h3           = 100_200 // H of the handoff after that, ordered in root epoch 3
	next3First   = 100_210
	t0           = 604_900 // UC time of the first record; later records add to it
)

// builder drives the root's own projection (rootrecords.State) and collects what it emits.
type builder struct {
	t     *testing.T
	state rootrecords.State
	recs  []rootrecords.Record
}

func (b *builder) block(epoch, round uint64) {
	b.t.Helper()
	s, err := b.state.Block(epoch, round)
	require.NoError(b.t, err)
	b.state = s
}

func (b *builder) commit(h, nextEpoch, nextFirst uint64, body string) {
	b.t.Helper()
	s, err := b.state.Commit(h, nextEpoch, nextFirst, true, label(body))
	require.NoError(b.t, err)
	b.state = s
}

func (b *builder) close(epoch uint64, d storage.ClosureData, round, ts uint64) rootrecords.Record {
	b.t.Helper()
	s, r, err := b.state.Close(epoch, d.Encode(), round, ts)
	require.NoError(b.t, err)
	b.state, b.recs = s, append(b.recs, r)
	return r
}

func (b *builder) ack(round, ts uint64, result, assignment [32]byte, evmEpoch uint64) rootrecords.Record {
	b.t.Helper()
	s, r, err := b.state.Ack(round, ts, result, assignment, evmEpoch)
	require.NoError(b.t, err)
	b.state, b.recs = s, append(b.recs, r)
	return r
}

func (b *builder) sessionClosed(result [32]byte, round, ts uint64) rootrecords.Record {
	b.t.Helper()
	s, r, err := b.state.SessionClosed(result, round, ts)
	require.NoError(b.t, err)
	b.state, b.recs = s, append(b.recs, r)
	return r
}

func (b *builder) json() []recordJSON {
	require.NoError(b.t, rootrecords.Verify(b.recs), "the projection's own log verifies")
	out := make([]recordJSON, len(b.recs))
	for i, r := range b.recs {
		out[i] = recordOf(r)
	}
	return out
}

// scenario is everything the root computes for the fixture: the ids it names each assignment by, the digests it derives from the
// frozen identity records, and the records its projection emits.
type scenario struct {
	result, genesis, primary, recovery [32]byte
	gExp, gKey, jExp, jKey, kExp, kKey [32]byte
}

func compute(t *testing.T) (scenario, publication) {
	t.Helper()
	p, d := loadPublication(t)
	var s scenario
	s.result = h32(t, p.ResultID)
	// custody keys the genesis assignment by the id it was deployed with; the root's is the assignment hash of the FULL genesis
	// configuration (ubft pos-relayer genesis / verify-genesis guard that the two are the same value). Here it is the fixture's.
	s.genesis = h32(t, p.IncumbentAssignmentID)
	// a primary assignment is keyed by its election result: the root derives the id, it does not use the assignment hash
	s.primary = evmassign.PrimaryAssignmentID(s.result)
	// a recovery re-installs the incumbent slate under the root's assignment hash of K, which custody learns from the RecoveryAck
	s.recovery = label("xrepo/recovery-assignment-hash-of-K")

	g, j := identities(t, p.IncumbentIdentities), identities(t, p.Identities)
	var err error
	s.gExp, err = evmassign.AssignmentExposureDigest(d, s.genesis, g)
	require.NoError(t, err)
	s.gKey, err = evmassign.KeyHistoryDigest(g)
	require.NoError(t, err)
	s.jExp, err = evmassign.AssignmentExposureDigest(d, s.primary, j)
	require.NoError(t, err)
	s.jKey, err = evmassign.KeyHistoryDigest(j)
	require.NoError(t, err)
	// K is the incumbent slate (the genesis identities, their lots) under K's own id
	s.kExp, err = evmassign.AssignmentExposureDigest(d, s.recovery, g)
	require.NoError(t, err)
	s.kKey, err = evmassign.KeyHistoryDigest(g)
	require.NoError(t, err)
	return s, p
}

func (s scenario) closure(id, exp, key [32]byte, hRound uint64, tag string) storage.ClosureData {
	return storage.ClosureData{AssignmentID: id, HRound: hRound, HRecordID: label("xrepo/h-record/" + tag), TerminalRoot: label("xrepo/terminal-root/" + tag),
		ExposureDigest: exp, KeyHistoryDigest: key}
}

func (s scenario) asg(role string, id, exp, key [32]byte) assignmentJSON {
	return assignmentJSON{Role: role, AssignmentID: hx(id[:]), ExposureDigest: hx(exp[:]), KeyDigest: hx(key[:])}
}

const (
	recoveryRootEpoch = 3
	recoveryEVMEpoch  = 2
)

func build(t *testing.T) goRecords {
	t.Helper()
	s, p := compute(t)
	zero := hx(make([]byte, 32))
	gen := func() assignmentJSON {
		a := s.asg("genesis", s.genesis, s.gExp, s.gKey)
		a.State, a.FirstRound, a.RootEpoch = "active", genesisFirst, 1
		return a
	}
	pri := func() assignmentJSON {
		a := s.asg("primary", s.primary, s.jExp, s.jKey)
		a.State, a.RootEpoch = "reserved", 2
		return a
	}

	// ---- recovery: the primary J is installed and never acknowledged; the incumbent slate returns as K ----
	rec := &builder{t: t, state: rootrecords.NewState(1, genesisFirst)}
	rec.commit(h1, 2, jFirst, "xrepo/body/J")
	rec.block(2, jFirst)
	cG := rec.close(1, s.closure(s.genesis, s.gExp, s.gKey, h1, "G"), jFirst, t0)
	rec.commit(h2, recoveryRootEpoch, next2First, "xrepo/body/K")
	rec.block(recoveryRootEpoch, next2First)
	cJ := rec.close(2, s.closure(s.primary, s.jExp, s.jKey, h2, "J"), next2First, t0+10)
	ra := rec.ack(next2First+5, t0+20, s.result, s.recovery, recoveryEVMEpoch)
	rec.commit(h3, 4, next3First, "xrepo/body/next")
	rec.block(4, next3First)
	cK := rec.close(recoveryRootEpoch, s.closure(s.recovery, s.kExp, s.kKey, h3, "K"), next3First, t0+30)

	jOffset := uint64(h1-genesisFirst) + 1 // p(1,h1)+1
	kOffset := jOffset + (h2 - jFirst) + 1 // p(2,h2)+1
	gClosed := gen()
	gClosed.Closed, gClosed.HRound, gClosed.PClose, gClosed.TClose = true, h1, cG.Progress, cG.UCTime
	jPending := pri()
	jPending.Pending, jPending.HRound, jPending.PClose, jPending.TClose = true, h2, cJ.Progress, cJ.UCTime
	jRecovered := pri()
	jRecovered.State, jRecovered.Closed, jRecovered.HRound, jRecovered.PClose, jRecovered.TClose = "active", true, h2, cJ.Progress, cJ.UCTime
	jRecovered.Offset, jRecovered.FirstRound = jOffset, jFirst
	k := s.asg("recovery", s.recovery, s.kExp, s.kKey)
	k.State, k.Offset, k.FirstRound, k.RootEpoch = "active", kOffset, next2First, recoveryRootEpoch
	kClosed := k
	kClosed.Closed, kClosed.HRound, kClosed.PClose, kClosed.TClose = true, h3, cK.Progress, cK.UCTime
	recovery := branchJSON{Name: "recovery", Records: rec.json(), Steps: []stepJSON{
		{AfterRecords: 1, LastAckedAssignment: hx(s.genesis[:]), PendingAssignment: zero, SessionState: "open", Assignments: []assignmentJSON{gClosed, pri()}},
		{AfterRecords: 2, LastAckedAssignment: hx(s.genesis[:]), PendingAssignment: hx(s.primary[:]), SessionState: "open", Assignments: []assignmentJSON{gClosed, jPending}},
		{AfterRecords: 3, LastAckedAssignment: hx(s.recovery[:]), PendingAssignment: zero, SessionState: "recovered", Assignments: []assignmentJSON{gClosed, jRecovered, k}},
		{AfterRecords: 4, LastAckedAssignment: hx(s.recovery[:]), PendingAssignment: zero, SessionState: "recovered", Assignments: []assignmentJSON{gClosed, jRecovered, kClosed}},
	}}
	require.Equal(t, rootrecords.KindRecoveryAck, ra.Kind, "two pending handoffs acknowledge as a RecoveryAck")

	// ---- ack: the primary J is acknowledged; later it is replaced and closed ----
	ack := &builder{t: t, state: rootrecords.NewState(1, genesisFirst)}
	ack.commit(h1, 2, jFirst, "xrepo/body/J")
	ack.block(2, jFirst)
	aG := ack.close(1, s.closure(s.genesis, s.gExp, s.gKey, h1, "G"), jFirst, t0)
	a := ack.ack(jFirst+2, t0+5, s.result, s.primary, 2)
	require.Equal(t, rootrecords.KindAck, a.Kind, "one pending handoff acknowledges as an Ack")
	ack.commit(h2, 3, next2First, "xrepo/body/next")
	ack.block(3, next2First)
	aJ := ack.close(2, s.closure(s.primary, s.jExp, s.jKey, h2, "J"), next2First, t0+10)
	gA := gen()
	gA.Closed, gA.HRound, gA.PClose, gA.TClose = true, h1, aG.Progress, aG.UCTime
	jActive := pri()
	jActive.State, jActive.Offset, jActive.FirstRound = "active", jOffset, jFirst
	jClosed := jActive
	jClosed.Closed, jClosed.HRound, jClosed.PClose, jClosed.TClose = true, h2, aJ.Progress, aJ.UCTime
	acked := branchJSON{Name: "ack", Records: ack.json(), Steps: []stepJSON{
		{AfterRecords: 1, LastAckedAssignment: hx(s.genesis[:]), PendingAssignment: zero, SessionState: "open", Assignments: []assignmentJSON{gA, pri()}},
		{AfterRecords: 2, LastAckedAssignment: hx(s.primary[:]), PendingAssignment: zero, SessionState: "acked", Assignments: []assignmentJSON{gA, jActive}},
		{AfterRecords: 3, LastAckedAssignment: hx(s.primary[:]), PendingAssignment: zero, SessionState: "acked", Assignments: []assignmentJSON{gA, jClosed}},
	}}

	// ---- session-closed: the root closes the result before any H (an Abort of its primary, or a RejectResult) ----
	sc := &builder{t: t, state: rootrecords.NewState(1, genesisFirst)}
	sc.sessionClosed(s.result, h1, t0)
	jAborted := pri()
	jAborted.State = "aborted"
	closed := branchJSON{Name: "session-closed", Records: sc.json(), Steps: []stepJSON{
		{AfterRecords: 1, LastAckedAssignment: hx(s.genesis[:]), PendingAssignment: zero, SessionState: "closed", Assignments: []assignmentJSON{gen(), jAborted}},
	}}

	return goRecords{
		Format: "UNICITY_XREPO_GO_RECORDS/v1",
		Note: "Produced by bft-core (XREPO_UPDATE=1 go test ./xrepo) from the contracts' publication fixture. The records are what the root's projection " +
			"emits with the ids and digests the root derives; custody must accept them verbatim. Do not edit by hand.",
		ResultID: p.ResultID, GenesisAssignmentID: hx(s.genesis[:]), PrimaryAssignmentID: hx(s.primary[:]), RecoveryAssignmentID: hx(s.recovery[:]),
		RecoveryRootEpoch: recoveryRootEpoch, RecoveryEVMEpoch: recoveryEVMEpoch,
		Branches: []branchJSON{recovery, acked, closed},
	}
}

func encode(t *testing.T, v any) []byte {
	t.Helper()
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", " ")
	require.NoError(t, enc.Encode(v))
	return buf.Bytes()
}

// The ids and digests the root derives from the identity records are the ones custody and election computed (Solidity is the source).
func TestTheRootsIdsAndDigestsAreCustodys(t *testing.T) {
	s, p := compute(t)
	require.Equal(t, h32(t, p.AssignmentID), s.primary, "the root names a primary assignment the way election derived it from the result")
	require.Equal(t, h32(t, p.Expected.ExposureDigest), s.jExp, "primary: exposure digest")
	require.Equal(t, h32(t, p.Expected.KeyDigest), s.jKey, "primary: key-history digest")
	require.Equal(t, h32(t, p.Expected.IncumbentExposureDigest), s.gExp, "genesis (the incumbent): exposure digest")
	require.Equal(t, h32(t, p.Expected.IncumbentKeyDigest), s.gKey, "genesis (the incumbent): key-history digest")
	require.NotEqual(t, s.gExp, s.kExp, "the same slate under K's id is another exposure digest")
	require.Equal(t, s.gKey, s.kKey, "and the same key history")
}

// The records this repository's projection emits for the fixture are the committed file the contracts replay (Go is the source).
// A change of an encoding, an id rule, a digest or the projection's arithmetic changes the file and fails here; XREPO_UPDATE=1
// rewrites it, and the copy in unicity-pos-contracts must then be replaced and replayed there.
func TestTheRootsRecordsAreTheCommittedVectors(t *testing.T) {
	got := encode(t, build(t))
	if os.Getenv("XREPO_UPDATE") == "1" {
		require.NoError(t, os.WriteFile(goRecordsPath, got, 0o644))
	}
	want, err := os.ReadFile(goRecordsPath)
	require.NoError(t, err)
	require.Equal(t, string(want), string(got), "the records the root would emit changed: regenerate with XREPO_UPDATE=1 and replay them in unicity-pos-contracts")
}

// ---- the file the contracts produce ----

type custodyView struct {
	Format   string `json:"format"`
	Branches []struct {
		Name  string     `json:"name"`
		Steps []stepJSON `json:"steps"`
	} `json:"branches"`
}

// What custody held after applying the root's records, as custody itself reports it (generated by the contracts), is what the root's
// projection says it holds: the same assignments under the same ids with the same digests, states, H rounds, closure anchors and
// offsets, the same last acknowledged assignment and the same session outcome, after every record.
func TestCustodysStateAfterTheRootsRecordsIsTheRoots(t *testing.T) {
	raw, err := os.ReadFile(custodyViewPath)
	require.NoError(t, err)
	var view custodyView
	require.NoError(t, json.Unmarshal(raw, &view))
	require.Equal(t, "UNICITY_XREPO_CUSTODY_VIEW/v1", view.Format)
	want := build(t)
	require.Len(t, view.Branches, len(want.Branches))
	for i, b := range want.Branches {
		require.Equal(t, b.Name, view.Branches[i].Name)
		require.Equal(t, b.Steps, view.Branches[i].Steps, "branch %s: custody's state after each record", b.Name)
	}
}
